class HoldPatternModel {
  const HoldPatternModel({
    required this.course,
    required this.turnRight,
    required this.legTime,
    required this.legDist,
    required this.minAlt,
    required this.maxAlt,
    required this.speed,
    required this.airport,
  });

  final double course;
  final bool turnRight;
  final double legTime;
  final double legDist;
  final int minAlt;
  final int maxAlt;
  final int speed;
  final String airport;

  factory HoldPatternModel.fromMap(Map<String, dynamic> map) {
    return HoldPatternModel(
      course: double.tryParse(map['crs']?.toString() ?? '0.0') ?? 0.0,
      turnRight: (map['turn']?.toString() ?? 'R') == 'R',
      legTime: double.tryParse(map['time']?.toString() ?? '0.0') ?? 0.0,
      legDist: double.tryParse(map['dist']?.toString() ?? '0.0') ?? 0.0,
      minAlt: int.tryParse(map['minAlt']?.toString() ?? '0') ?? 0,
      maxAlt: int.tryParse(map['maxAlt']?.toString() ?? '0') ?? 0,
      speed: int.tryParse(map['spd']?.toString() ?? '0') ?? 0,
      airport: map['apt']?.toString() ?? '',
    );
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'crs': course,
        'turn': turnRight ? 'R' : 'L',
        'time': legTime,
        'dist': legDist,
        'minAlt': minAlt,
        'maxAlt': maxAlt,
        'spd': speed,
        'apt': airport,
      };
}

class HoldData {
  HoldData._();

  static final Map<String, List<HoldPatternModel>> _cache =
      <String, List<HoldPatternModel>>{};

  static List<HoldPatternModel>? getHold(String fixIdent) {
    final String key = fixIdent.trim().toUpperCase();
    if (key.isEmpty) return null;

    final dynamic rawData = _holds[key];
    if (rawData == null || rawData is! List) return null;

    return _cache.putIfAbsent(
      key,
      () => rawData
          .map((p) => HoldPatternModel.fromMap(Map<String, dynamic>.from(p)))
          .toList(),
    );
  }

  static bool containsHold(String fixIdent) =>
